//! MOD2026: the 2x versions of the three glyph fonts for the 2x display layer
//! (`docs/mod2026/fonts/README.md`). Each 2x glyph is the Scale2x image of the original
//! glyph, so every advance and height is exactly twice the original's. The files are
//! generated by `examples/hires_fonts.rs` and embedded in the program.

use crate::font::{Font, FontId, GLYPH_COUNT, Glyph};

const MICRO4: &str = include_str!("../../../docs/mod2026/fonts/micro4.txt");
const FLOW: &str = include_str!("../../../docs/mod2026/fonts/flow.txt");
const NEWBOLD: &str = include_str!("../../../docs/mod2026/fonts/newbold.txt");

/// The name of the 2x font file of `id` in `docs/mod2026/fonts/`.
pub fn file_name(id: FontId) -> &'static str {
    match id {
        FontId::Micro4 => "micro4.txt",
        FontId::Flow => "flow.txt",
        FontId::Newbold => "newbold.txt",
    }
}

fn embedded(id: FontId) -> &'static str {
    match id {
        FontId::Micro4 => MICRO4,
        FontId::Flow => FLOW,
        FontId::Newbold => NEWBOLD,
    }
}

/// Builds a glyph of `width` columns from rows of set flags.
fn from_rows(width: usize, rows: &[Vec<bool>]) -> Glyph {
    let row_bytes = width.div_ceil(8);
    let mut bits = vec![0u8; rows.len() * row_bytes];
    for (y, row) in rows.iter().enumerate() {
        for (x, _) in row.iter().enumerate().filter(|&(_, &set)| set) {
            bits[y * row_bytes + x / 8] |= 0x80 >> (x % 8);
        }
    }
    Glyph {
        width: width as u8,
        bits,
    }
}

/// The Scale2x (EPX) image of glyph `g` with `height` rows; pixels outside the cell count
/// as clear. The result is `2 * width` wide and `2 * height` high.
pub fn scale2x(g: &Glyph, height: usize) -> Glyph {
    let w = g.width as usize;
    let p = |c: isize, r: isize| {
        (0..w as isize).contains(&c)
            && (0..height as isize).contains(&r)
            && g.pixel(c as usize, r as usize)
    };
    let mut rows = vec![vec![false; 2 * w]; 2 * height];
    for r in 0..height as isize {
        for c in 0..w as isize {
            let (e, b, d, f, h) = (p(c, r), p(c, r - 1), p(c - 1, r), p(c + 1, r), p(c, r + 1));
            let quad = if b != h && d != f {
                [
                    if d == b { d } else { e },
                    if b == f { f } else { e },
                    if d == h { d } else { e },
                    if h == f { f } else { e },
                ]
            } else {
                [e; 4]
            };
            for (k, v) in quad.into_iter().enumerate() {
                rows[2 * r as usize + k / 2][2 * c as usize + k % 2] = v;
            }
        }
    }
    from_rows(2 * w, &rows)
}

/// The 2x font file of `font`: a header, then one `glyph 0xNN` block per character code
/// `0x20..=0x7e` with `2 * height` rows of `#` (set) and `.` (clear).
pub fn font_text(font: &Font) -> String {
    let height = font.height as usize;
    let mut out = format!(
        "# MOD2026: 2x version of {name} (docs/mod2026/fonts/README.md): the Scale2x image of\n\
         # every original glyph. Generated by\n\
         # `cargo run -p bmp-formats --example hires_fonts -- <data dir>`. Do not edit by hand.\n\
         font {name}\nheight {}\n",
        2 * height,
        name = font.name,
    );
    for (i, g) in font.glyphs.iter().enumerate() {
        assert!(g.width != 0, "{}: glyph {i} has no width", font.name);
        let big = scale2x(g, height);
        out += &format!("glyph {:#04x}\n", 0x20 + i);
        for row in 0..2 * height {
            out.extend((0..big.width as usize).map(|c| if big.pixel(c, row) { '#' } else { '.' }));
            out.push('\n');
        }
    }
    out
}

/// The 2x glyphs of font `id` for the character codes `0x20..=0x7e`, in order.
///
/// # Panics
/// When the embedded file is malformed.
pub fn glyphs(id: FontId) -> Vec<Glyph> {
    parse(embedded(id)).unwrap_or_else(|e| panic!("{}: {e}", file_name(id)))
}

fn parse(text: &str) -> Result<Vec<Glyph>, String> {
    let mut height = None;
    let mut blocks: Vec<Vec<Vec<bool>>> = Vec::new();
    for line in text.lines().map(str::trim) {
        if line.is_empty() || line.starts_with("# ") || line.starts_with("font ") {
            continue;
        }
        if let Some(h) = line.strip_prefix("height ") {
            height = Some(
                h.parse::<usize>()
                    .map_err(|_| format!("bad height {h:?}"))?,
            );
        } else if let Some(code) = line.strip_prefix("glyph ") {
            if code != format!("{:#04x}", 0x20 + blocks.len()) {
                return Err(format!("glyph {code} out of order"));
            }
            blocks.push(Vec::new());
        } else if line.bytes().all(|p| b"#.".contains(&p)) {
            blocks
                .last_mut()
                .ok_or("pixel row before the first glyph")?
                .push(line.bytes().map(|p| p == b'#').collect());
        } else {
            return Err(format!("bad line {line:?}"));
        }
    }
    let height = height.ok_or("no height")?;
    if blocks.len() != GLYPH_COUNT {
        return Err(format!("{} glyphs, expected {GLYPH_COUNT}", blocks.len()));
    }
    blocks
        .iter()
        .enumerate()
        .map(|(i, rows)| {
            let width = rows.first().map_or(0, Vec::len);
            if rows.len() != height || !(1..=0xff).contains(&width) {
                return Err(format!("glyph {:#04x}: bad size", 0x20 + i));
            }
            if rows.iter().any(|r| r.len() != width) {
                return Err(format!("glyph {:#04x}: ragged rows", 0x20 + i));
            }
            Ok(from_rows(width, rows))
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::font::FontSet;

    fn glyph(art: &[&str]) -> Glyph {
        let rows: Vec<Vec<bool>> = art
            .iter()
            .map(|r| r.bytes().map(|p| p == b'#').collect())
            .collect();
        from_rows(art[0].len(), &rows)
    }

    /// The nearest-neighbour doubling of `g`.
    fn doubled(g: &Glyph, height: usize) -> Glyph {
        let w = g.width as usize;
        let rows: Vec<Vec<bool>> = (0..2 * height)
            .map(|r| (0..2 * w).map(|c| g.pixel(c / 2, r / 2)).collect())
            .collect();
        from_rows(2 * w, &rows)
    }

    #[test]
    fn scale2x_rounds_diagonals_and_keeps_bars() {
        let diagonal = glyph(&["#..", ".#.", "..#"]);
        assert_eq!(
            scale2x(&diagonal, 3),
            glyph(&["##....", "###...", ".###..", "..###.", "...###", "....##",])
        );
        for art in [&["...", ".#.", "..."], &["...", "###", "..."]] {
            let g = glyph(art);
            assert_eq!(scale2x(&g, 3), doubled(&g, 3), "{art:?}");
        }
    }

    #[test]
    fn font_text_round_trips() {
        let mut glyphs = vec![glyph(&["#.", ".#"]); GLYPH_COUNT];
        glyphs[1] = glyph(&["###", "#.."]);
        let font = Font {
            name: "test.font".into(),
            height: 2,
            descent: 0,
            glyphs,
        };
        let parsed = parse(&font_text(&font)).unwrap();
        let want: Vec<Glyph> = font.glyphs.iter().map(|g| scale2x(g, 2)).collect();
        assert_eq!(parsed, want);
    }

    /// For every font and every glyph the 2x advance and height are twice the original's
    /// (the heights below are the shipped fonts'; the widths need `BMP_DATA`).
    #[test]
    fn hires_glyphs_have_twice_the_metrics() {
        for (id, height) in [
            (FontId::Micro4, 6),
            (FontId::Flow, 8),
            (FontId::Newbold, 16),
        ] {
            let gs = glyphs(id);
            assert_eq!(gs.len(), GLYPH_COUNT);
            for g in &gs {
                assert_eq!(g.bits.len(), 2 * height * g.row_bytes(), "{}", id.name());
            }
        }
        let Some(set) = fonts() else { return };
        for id in FontId::ALL {
            let font = set.get(id);
            for (i, (big, orig)) in glyphs(id).iter().zip(&font.glyphs).enumerate() {
                assert_eq!(big.width, 2 * orig.width, "{} glyph {i}", id.name());
                assert_eq!(
                    big.bits.len() / big.row_bytes(),
                    2 * font.height as usize,
                    "{} glyph {i}",
                    id.name()
                );
            }
        }
    }

    /// Needs `BMP_DATA`.
    #[test]
    fn most_hires_glyphs_have_real_detail() {
        let Some(set) = fonts() else { return };
        for id in FontId::ALL {
            let font = set.get(id);
            let height = font.height as usize;
            let detailed = glyphs(id)
                .iter()
                .zip(&font.glyphs)
                .filter(|(big, orig)| **big != doubled(orig, height))
                .count();
            assert!(
                2 * detailed >= GLYPH_COUNT,
                "{}: {detailed} of {GLYPH_COUNT} glyphs differ from the doubling",
                id.name()
            );
        }
    }

    /// The committed files are exactly what the generator writes (needs `BMP_DATA`).
    #[test]
    fn committed_fonts_are_the_generator_output() {
        let Some(set) = fonts() else { return };
        for id in FontId::ALL {
            assert!(
                font_text(set.get(id)) == embedded(id),
                "docs/mod2026/fonts/{} is not the generator output; regenerate it",
                file_name(id)
            );
        }
    }

    fn fonts() -> Option<FontSet> {
        Some(FontSet::load(&crate::data_dir()?).expect("fonts load"))
    }
}
